27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * ARP block for IPv4, ethernet frame interface
33	 */
34	module arp #
35	(
36	    // Width of AXI stream interfaces in bits
37	    parameter DATA_WIDTH = 8,
38	    // Propagate tkeep signal
39	    // If disabled, tkeep assumed to be 1'b1
40	    parameter KEEP_ENABLE = (DATA_WIDTH>8),
41	    // tkeep signal width (words per cycle)
42	    parameter KEEP_WIDTH = (DATA_WIDTH/8),
43	    // Log2 of ARP cache size
44	    parameter CACHE_ADDR_WIDTH = 9,
45	    // ARP request retry count
46	    parameter REQUEST_RETRY_COUNT = 4,
47	    // ARP request retry interval (in cycles)
48	    parameter REQUEST_RETRY_INTERVAL = 125000000*2,
49	    // ARP request timeout (in cycles)
50	    parameter REQUEST_TIMEOUT = 125000000*30
51	)
52	(
53	    input  wire                   clk,
54	    input  wire                   rst,
55	
56	    /*
57	     * Ethernet frame input
58	     */
59	    input  wire                   s_eth_hdr_valid,
60	    output wire                   s_eth_hdr_ready,
61	    input  wire [47:0]            s_eth_dest_mac,
62	    input  wire [47:0]            s_eth_src_mac,
63	    input  wire [15:0]            s_eth_type,
64	    input  wire [DATA_WIDTH-1:0]  s_eth_payload_axis_tdata,
65	    input  wire [KEEP_WIDTH-1:0]  s_eth_payload_axis_tkeep,
66	    input  wire                   s_eth_payload_axis_tvalid,
67	    output wire                   s_eth_payload_axis_tready,
68	    input  wire                   s_eth_payload_axis_tlast,
69	    input  wire                   s_eth_payload_axis_tuser,
70	
71	    /*
72	     * Ethernet frame output
73	     */
74	    output wire                   m_eth_hdr_valid,
75	    input  wire                   m_eth_hdr_ready,
76	    output wire [47:0]            m_eth_dest_mac,
77	    output wire [47:0]            m_eth_src_mac,
78	    output wire [15:0]            m_eth_type,
79	    output wire [DATA_WIDTH-1:0]  m_eth_payload_axis_tdata,
80	    output wire [KEEP_WIDTH-1:0]  m_eth_payload_axis_tkeep,
81	    output wire                   m_eth_payload_axis_tvalid,
82	    input  wire                   m_eth_payload_axis_tready,
83	    output wire                   m_eth_payload_axis_tlast,
84	    output wire                   m_eth_payload_axis_tuser,
85	
86	    /*
87	     * ARP requests
88	     */
89	    input  wire                   arp_request_valid,
90	    output wire                   arp_request_ready,
91	    input  wire [31:0]            arp_request_ip,
92	    output wire                   arp_response_valid,
93	    input  wire                   arp_response_ready,
94	    output wire                   arp_response_error,
95	    output wire [47:0]            arp_response_mac,
96	
97	    /*
98	     * Configuration
99	     */
100	    input  wire [47:0]            local_mac,
101	    input  wire [31:0]            local_ip,
102	    input  wire [31:0]            gateway_ip,
103	    input  wire [31:0]            subnet_mask,
104	    input  wire                   clear_cache
105	);
106	
107	localparam [15:0]
108	    ARP_OPER_ARP_REQUEST = 16'h0001,
109	    ARP_OPER_ARP_REPLY = 16'h0002,
110	    ARP_OPER_INARP_REQUEST = 16'h0008,
111	    ARP_OPER_INARP_REPLY = 16'h0009;
112	
113	wire incoming_frame_valid;
114	reg incoming_frame_ready;
115	wire [47:0] incoming_eth_dest_mac;
116	wire [47:0] incoming_eth_src_mac;
117	wire [15:0] incoming_eth_type;
118	wire [15:0] incoming_arp_htype;
119	wire [15:0] incoming_arp_ptype;
120	wire [7:0]  incoming_arp_hlen;
121	wire [7:0]  incoming_arp_plen;
122	wire [15:0] incoming_arp_oper;
123	wire [47:0] incoming_arp_sha;
124	wire [31:0] incoming_arp_spa;
125	wire [47:0] incoming_arp_tha;
126	wire [31:0] incoming_arp_tpa;
127	
128	/*
129	 * ARP frame processing
130	 */
131	arp_eth_rx #(
132	    .DATA_WIDTH(DATA_WIDTH),
133	    .KEEP_ENABLE(KEEP_ENABLE),
134	    .KEEP_WIDTH(KEEP_WIDTH)
135	)
136	arp_eth_rx_inst (
137	    .clk(clk),
138	    .rst(rst),
139	    // Ethernet frame input
140	    .s_eth_hdr_valid(s_eth_hdr_valid),
141	    .s_eth_hdr_ready(s_eth_hdr_ready),
142	    .s_eth_dest_mac(s_eth_dest_mac),
143	    .s_eth_src_mac(s_eth_src_mac),
144	    .s_eth_type(s_eth_type),
145	    .s_eth_payload_axis_tdata(s_eth_payload_axis_tdata),
146	    .s_eth_payload_axis_tkeep(s_eth_payload_axis_tkeep),
147	    .s_eth_payload_axis_tvalid(s_eth_payload_axis_tvalid),
148	    .s_eth_payload_axis_tready(s_eth_payload_axis_tready),
149	    .s_eth_payload_axis_tlast(s_eth_payload_axis_tlast),
150	    .s_eth_payload_axis_tuser(s_eth_payload_axis_tuser),
151	    // ARP frame output
152	    .m_frame_valid(incoming_frame_valid),
153	    .m_frame_ready(incoming_frame_ready),
154	    .m_eth_dest_mac(incoming_eth_dest_mac),
155	    .m_eth_src_mac(incoming_eth_src_mac),
156	    .m_eth_type(incoming_eth_type),
157	    .m_arp_htype(incoming_arp_htype),
158	    .m_arp_ptype(incoming_arp_ptype),
159	    .m_arp_hlen(incoming_arp_hlen),
160	    .m_arp_plen(incoming_arp_plen),
161	    .m_arp_oper(incoming_arp_oper),
162	    .m_arp_sha(incoming_arp_sha),
163	    .m_arp_spa(incoming_arp_spa),
164	    .m_arp_tha(incoming_arp_tha),
165	    .m_arp_tpa(incoming_arp_tpa),
166	    // Status signals
167	    .busy(),
168	    .error_header_early_termination(),
169	    .error_invalid_header()
170	);
171	
172	reg outgoing_frame_valid_reg = 1'b0, outgoing_frame_valid_next;
173	wire outgoing_frame_ready;
174	reg [47:0] outgoing_eth_dest_mac_reg = 48'd0, outgoing_eth_dest_mac_next;
175	reg [15:0] outgoing_arp_oper_reg = 16'd0, outgoing_arp_oper_next;
176	reg [47:0] outgoing_arp_tha_reg = 48'd0, outgoing_arp_tha_next;
177	reg [31:0] outgoing_arp_tpa_reg = 32'd0, outgoing_arp_tpa_next;
178	
179	arp_eth_tx #(
180	    .DATA_WIDTH(DATA_WIDTH),
181	    .KEEP_ENABLE(KEEP_ENABLE),
182	    .KEEP_WIDTH(KEEP_WIDTH)
183	)
184	arp_eth_tx_inst (
185	    .clk(clk),
186	    .rst(rst),
187	    // ARP frame input
188	    .s_frame_valid(outgoing_frame_valid_reg),
189	    .s_frame_ready(outgoing_frame_ready),
190	    .s_eth_dest_mac(outgoing_eth_dest_mac_reg),
191	    .s_eth_src_mac(local_mac),
192	    .s_eth_type(16'h0806),
193	    .s_arp_htype(16'h0001),
194	    .s_arp_ptype(16'h0800),
195	    .s_arp_oper(outgoing_arp_oper_reg),
196	    .s_arp_sha(local_mac),
197	    .s_arp_spa(local_ip),
198	    .s_arp_tha(outgoing_arp_tha_reg),
199	    .s_arp_tpa(outgoing_arp_tpa_reg),
200	    // Ethernet frame output
201	    .m_eth_hdr_valid(m_eth_hdr_valid),
202	    .m_eth_hdr_ready(m_eth_hdr_ready),
203	    .m_eth_dest_mac(m_eth_dest_mac),
204	    .m_eth_src_mac(m_eth_src_mac),
205	    .m_eth_type(m_eth_type),
206	    .m_eth_payload_axis_tdata(m_eth_payload_axis_tdata),
207	    .m_eth_payload_axis_tkeep(m_eth_payload_axis_tkeep),
208	    .m_eth_payload_axis_tvalid(m_eth_payload_axis_tvalid),
209	    .m_eth_payload_axis_tready(m_eth_payload_axis_tready),
210	    .m_eth_payload_axis_tlast(m_eth_payload_axis_tlast),
211	    .m_eth_payload_axis_tuser(m_eth_payload_axis_tuser),
212	    // Status signals
213	    .busy()
214	);
215	
216	reg cache_query_request_valid_reg = 1'b0, cache_query_request_valid_next;
217	reg [31:0] cache_query_request_ip_reg = 32'd0, cache_query_request_ip_next;
218	wire cache_query_response_valid;
219	wire cache_query_response_error;
220	wire [47:0] cache_query_response_mac;
221	
222	reg cache_write_request_valid_reg = 1'b0, cache_write_request_valid_next;
223	reg [31:0] cache_write_request_ip_reg = 32'd0, cache_write_request_ip_next;
224	reg [47:0] cache_write_request_mac_reg = 48'd0, cache_write_request_mac_next;
225	
226	/*
227	 * ARP cache
228	 */
229	arp_cache #(
230	    .CACHE_ADDR_WIDTH(CACHE_ADDR_WIDTH)
231	)
232	arp_cache_inst (
233	    .clk(clk),
234	    .rst(rst),
235	    // Query cache
236	    .query_request_valid(cache_query_request_valid_reg),
237	    .query_request_ready(),
238	    .query_request_ip(cache_query_request_ip_reg),
239	    .query_response_valid(cache_query_response_valid),
240	    .query_response_ready(1'b1),
241	    .query_response_error(cache_query_response_error),
242	    .query_response_mac(cache_query_response_mac),
243	    // Write cache
244	    .write_request_valid(cache_write_request_valid_reg),
245	    .write_request_ready(),
246	    .write_request_ip(cache_write_request_ip_reg),
247	    .write_request_mac(cache_write_request_mac_reg),
248	    // Configuration
249	    .clear_cache(clear_cache)
250	);
251	
252	reg arp_request_operation_reg = 1'b0, arp_request_operation_next;
253	
254	reg arp_request_ready_reg = 1'b0, arp_request_ready_next;
255	reg [31:0] arp_request_ip_reg = 32'd0, arp_request_ip_next;
256	
257	reg arp_response_valid_reg = 1'b0, arp_response_valid_next;
258	reg arp_response_error_reg = 1'b0, arp_response_error_next;
259	reg [47:0] arp_response_mac_reg = 48'd0, arp_response_mac_next;
260	
261	reg [5:0] arp_request_retry_cnt_reg = 6'd0, arp_request_retry_cnt_next;
262	reg [35:0] arp_request_timer_reg = 36'd0, arp_request_timer_next;
263	
264	assign arp_request_ready = arp_request_ready_reg;
265	
266	assign arp_response_valid = arp_response_valid_reg;
267	assign arp_response_error = arp_response_error_reg;
268	assign arp_response_mac = arp_response_mac_reg;
269	
270	always @* begin
271	    incoming_frame_ready = 1'b0;
272	
273	    outgoing_frame_valid_next = outgoing_frame_valid_reg && !outgoing_frame_ready;
274	    outgoing_eth_dest_mac_next = outgoing_eth_dest_mac_reg;
275	    outgoing_arp_oper_next = outgoing_arp_oper_reg;
276	    outgoing_arp_tha_next = outgoing_arp_tha_reg;
277	    outgoing_arp_tpa_next = outgoing_arp_tpa_reg;
278	
279	    cache_query_request_valid_next = 1'b0;
280	    cache_query_request_ip_next = cache_query_request_ip_reg;
281	
282	    cache_write_request_valid_next = 1'b0;
283	    cache_write_request_mac_next = cache_write_request_mac_reg;
284	    cache_write_request_ip_next = cache_write_request_ip_reg;
285	
286	    arp_request_ready_next = 1'b0;
287	    arp_request_ip_next = arp_request_ip_reg;
288	    arp_request_operation_next = arp_request_operation_reg;
289	    arp_request_retry_cnt_next = arp_request_retry_cnt_reg;
290	    arp_request_timer_next = arp_request_timer_reg;
291	    arp_response_valid_next = arp_response_valid_reg && !arp_response_ready;
292	    arp_response_error_next = 1'b0;
293	    arp_response_mac_next = 48'd0;
294	
295	    // manage incoming frames
296	    incoming_frame_ready = outgoing_frame_ready;
297	    if (incoming_frame_valid && incoming_frame_ready) begin
298	        if (incoming_eth_type == 16'h0806 && incoming_arp_htype == 16'h0001 && incoming_arp_ptype == 16'h0800) begin
299	            // store sender addresses in cache
300	            cache_write_request_valid_next = 1'b1;
301	            cache_write_request_ip_next = incoming_arp_spa;
302	            cache_write_request_mac_next = incoming_arp_sha;
303	            if (incoming_arp_oper == ARP_OPER_ARP_REQUEST) begin
304	                // ARP request
305	                if (incoming_arp_tpa == local_ip) begin
306	                    // send reply frame to valid incoming request
307	                    outgoing_frame_valid_next = 1'b1;
308	                    outgoing_eth_dest_mac_next = incoming_eth_src_mac;
309	                    outgoing_arp_oper_next = ARP_OPER_ARP_REPLY;
310	                    outgoing_arp_tha_next = incoming_arp_sha;
311	                    outgoing_arp_tpa_next = incoming_arp_spa;
312	                end
313	            end else if (incoming_arp_oper == ARP_OPER_INARP_REQUEST) begin
314	                // INARP request
315	                if (incoming_arp_tha == local_mac) begin
316	                    // send reply frame to valid incoming request
317	                    outgoing_frame_valid_next = 1'b1;
318	                    outgoing_eth_dest_mac_next = incoming_eth_src_mac;
319	                    outgoing_arp_oper_next = ARP_OPER_INARP_REPLY;
320	                    outgoing_arp_tha_next = incoming_arp_sha;
321	                    outgoing_arp_tpa_next = incoming_arp_spa;
322	                end 
323	            end
324	        end
325	    end
326	
327	    // manage ARP lookup requests
328	    if (arp_request_operation_reg) begin
329	        arp_request_ready_next = 1'b0;
330	        cache_query_request_valid_next = 1'b1;
331	        arp_request_timer_next = arp_request_timer_reg - 1;
332	        // if we got a response, it will go in the cache, so when the query succeds, we're done
333	        if (cache_query_response_valid && !cache_query_response_error) begin
334	            arp_request_operation_next = 1'b0;
335	            cache_query_request_valid_next = 1'b0;
336	            arp_response_valid_next = 1'b1;
337	            arp_response_error_next = 1'b0;
338	            arp_response_mac_next = cache_query_response_mac;
339	        end
340	        // timer timeout
341	        if (arp_request_timer_reg == 0) begin
342	            if (arp_request_retry_cnt_reg > 0) begin
343	                // have more retries
344	                // send ARP request frame
345	                outgoing_frame_valid_next = 1'b1;
346	                outgoing_eth_dest_mac_next = 48'hffffffffffff;
347	                outgoing_arp_oper_next = ARP_OPER_ARP_REQUEST;
348	                outgoing_arp_tha_next = 48'h000000000000;
349	                outgoing_arp_tpa_next = arp_request_ip_reg;
350	                arp_request_retry_cnt_next = arp_request_retry_cnt_reg - 1;
351	                if (arp_request_retry_cnt_reg > 1) begin
352	                    arp_request_timer_next = REQUEST_RETRY_INTERVAL;
353	                end else begin
354	                    arp_request_timer_next = REQUEST_TIMEOUT;
355	                end
356	            end else begin
357	                // out of retries
358	                arp_request_operation_next = 1'b0;
359	                arp_response_valid_next = 1'b1;
360	                arp_response_error_next = 1'b1;
361	                cache_query_request_valid_next = 1'b0;
362	            end
363	        end
364	    end else begin
365	        arp_request_ready_next = !arp_response_valid_next;
366	        if (cache_query_request_valid_reg) begin
367	            cache_query_request_valid_next = 1'b1;
368	            if (cache_query_response_valid) begin
369	                if (cache_query_response_error) begin
370	                    arp_request_operation_next = 1'b1;
371	                    // send ARP request frame
372	                    outgoing_frame_valid_next = 1'b1;
373	                    outgoing_eth_dest_mac_next = 48'hffffffffffff;
374	                    outgoing_arp_oper_next = ARP_OPER_ARP_REQUEST;
375	                    outgoing_arp_tha_next = 48'h000000000000;
376	                    outgoing_arp_tpa_next = arp_request_ip_reg;
377	                    arp_request_retry_cnt_next = REQUEST_RETRY_COUNT-1;
378	                    arp_request_timer_next = REQUEST_RETRY_INTERVAL;
379	                end else begin
380	                    cache_query_request_valid_next = 1'b0;
381	                    arp_response_valid_next = 1'b1;
382	                    arp_response_error_next = 1'b0;
383	                    arp_response_mac_next = cache_query_response_mac;
384	                end
385	            end
386	        end else if (arp_request_valid && arp_request_ready) begin
387	            if (arp_request_ip == 32'hffffffff) begin
388	                // broadcast address; use broadcast MAC address
389	                arp_response_valid_next = 1'b1;
390	                arp_response_error_next = 1'b0;
391	                arp_response_mac_next = 48'hffffffffffff;
392	            end else if (((arp_request_ip ^ gateway_ip) & subnet_mask) == 0) begin
393	                // within subnet
394	                // (no bits differ between request IP and gateway IP where subnet mask is set)
395	                if (~(arp_request_ip | subnet_mask) == 0) begin
396	                    // broadcast address; use broadcast MAC address
397	                    // (all bits in request IP set where subnet mask is clear)
398	                    arp_response_valid_next = 1'b1;
399	                    arp_response_error_next = 1'b0;
400	                    arp_response_mac_next = 48'hffffffffffff;
401	                end else begin
402	                    // unicast address; look up IP directly
403	                    cache_query_request_valid_next = 1'b1;
404	                    cache_query_request_ip_next = arp_request_ip;
405	                    arp_request_ip_next = arp_request_ip;
406	                end
407	            end else begin
408	                // outside of subnet, so look up gateway address
409	                cache_query_request_valid_next = 1'b1;
410	                cache_query_request_ip_next = gateway_ip;
411	                arp_request_ip_next = gateway_ip;
412	            end
413	        end
414	    end
415	end
416	
417	always @(posedge clk) begin
418	    if (rst) begin
419	        outgoing_frame_valid_reg <= 1'b0;
420	        cache_query_request_valid_reg <= 1'b0;
421	        cache_write_request_valid_reg <= 1'b0;
422	        arp_request_ready_reg <= 1'b0;
423	        arp_request_operation_reg <= 1'b0;
424	        arp_request_retry_cnt_reg <= 6'd0;
425	        arp_request_timer_reg <= 36'd0;
426	        arp_response_valid_reg <= 1'b0;
427	    end else begin
428	        outgoing_frame_valid_reg <= outgoing_frame_valid_next;
429	        cache_query_request_valid_reg <= cache_query_request_valid_next;
430	        cache_write_request_valid_reg <= cache_write_request_valid_next;
431	        arp_request_ready_reg <= arp_request_ready_next;
432	        arp_request_operation_reg <= arp_request_operation_next;
433	        arp_request_retry_cnt_reg <= arp_request_retry_cnt_next;
434	        arp_request_timer_reg <= arp_request_timer_next;
435	        arp_response_valid_reg <= arp_response_valid_next;
436	    end
437	
438	    cache_query_request_ip_reg <= cache_query_request_ip_next;
439	    outgoing_eth_dest_mac_reg <= outgoing_eth_dest_mac_next;
440	    outgoing_arp_oper_reg <= outgoing_arp_oper_next;
441	    outgoing_arp_tha_reg <= outgoing_arp_tha_next;
442	    outgoing_arp_tpa_reg <= outgoing_arp_tpa_next;
443	    cache_write_request_mac_reg <= cache_write_request_mac_next;
444	    cache_write_request_ip_reg <= cache_write_request_ip_next;
445	    arp_request_ip_reg <= arp_request_ip_next;
446	    arp_response_error_reg <= arp_response_error_next;
447	    arp_response_mac_reg <= arp_response_mac_next;
448	end
449	
450	endmodule
451	
452	`resetall
453

